
import {LESSONS, PARTS, BY_CHAR} from './data.mjs';
import {STORAGE_KEY, isCorrect, localDate} from './engine.mjs';
import {STUDY_KEY, normalizeStudy, partCandidates, positions, recipe, recordStudy, recordPart, studySession, studyStats} from './study.mjs';
import {samplePath, bounds, fitStrokes, compareInk, strokePath} from './handwriting.mjs';
import {placementAt} from './placement.mjs';

const app=document.querySelector('#app');
const html=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress=normalizeStudy(null),storage=true,glyphs={},templates={},partTemplates={},partPaths={},screen='home',session=null,suspended=null,message='',detail=null;
let drawing=null,drag=null,nativePart=null,suppressClick=false;
try{progress=normalizeStudy(JSON.parse(localStorage.getItem(STUDY_KEY)||localStorage.getItem(STORAGE_KEY)||'null'));}catch{storage=false;}
function save(){try{localStorage.setItem(STUDY_KEY,JSON.stringify(progress));storage=true;}catch{storage=false;}}
function say(text){document.querySelector('#announcer').textContent=text;}
function speak(text){
  if(!window.speechSynthesis){say('読み上げに対応していないブラウザーです。画面のことばで確かめよう。');return;}
  window.speechSynthesis.cancel();const u=new window.SpeechSynthesisUtterance(text);u.lang='ja-JP';u.rate=.8;window.speechSynthesis.speak(u);
}
function sound(){
  if(!progress.settings.sound)return;
  try{const ctx=new (window.AudioContext||window.webkitAudioContext)();[523,659,784].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=f;g.gain.setValueAtTime(.04,ctx.currentTime+i*.08);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.08+.25);o.start(ctx.currentTime+i*.08);o.stop(ctx.currentTime+i*.08+.26);});setTimeout(()=>ctx.close(),700);}catch{}
}
function go(next){drawing=null;drag?.ghost?.remove();drag=null;window.speechSynthesis?.cancel();screen=next;message='';render();window.scrollTo({top:0,behavior:'instant'});}
const btn=(action,label,extra='',cls='soft')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function glyph(char,animated=false){
  const groups=glyphs[char];if(!groups)return `<span class="glyph-fallback">${html(char)}</span>`;
  let n=0;return `<svg class="kanji-glyph ${animated?'stroke-animation':''}" viewBox="0 0 109 109" role="img" aria-label="${html(char)}">${groups.map((g,i)=>`<g class="group-${i}">${g.map(d=>`<path d="${d}" style="--stroke:${n++}" pathLength="1"/>`).join('')}</g>`).join('')}</svg>`;
}
function partGlyph(id,{animate=false,numbered=false}={}){
  const paths=partPaths[id],b=bounds(partTemplates[id]||[]);if(!paths||!b)return `<span class="part-glyph-text">${PARTS[id][0]}</span>`;
  return `<svg class="component-glyph ${animate?'stroke-animation':''}" viewBox="${b.left-6} ${b.top-6} ${b.width+12} ${b.height+12}" role="img" aria-label="部品の形">${paths.map((d,i)=>`<path d="${d}" style="--stroke:${i}" pathLength="1"/>${numbered?`<text x="${partTemplates[id][i][0][0]-3}" y="${partTemplates[id][i][0][1]-3}">${i+1}</text>`:''}`).join('')}</svg>`;
}
function modeSwitch(){return `<div class="mode-switch" role="group" aria-label="形を出すモード">${['shape','pen'].map(mode=>`<button data-action="mode" data-mode="${mode}" aria-pressed="${progress.settings.mode===mode}" class="${progress.settings.mode===mode?'active':''}">${mode==='pen'?'✎ ペンで書く':'▦ 形から選ぶ'}</button>`).join('')}</div>`;}
function shell(body){const st=studyStats(progress);return `<div class="app-shell"><aside class="app-sidebar"><button class="app-brand" data-action="home"><span class="brand-symbol">＋<i>✦</i></span><span>カンジ工房<small>ことばから、かたちへ。</small></span></button><nav aria-label="メインメニュー">${btn('home','⌂ ホーム','',screen==='home'?'nav-link current':'nav-link')}${btn('parts','◇ 部品のれんしゅう','',screen==='parts'?'nav-link current':'nav-link')}${btn('collection','▦ 漢字ずかん','',screen==='collection'?'nav-link current':'nav-link')}</nav><div class="sidebar-note"><span>✦</span><p>「にんべん」って、<br>どんな形だったかな？</p><small>ことばと形を、つなげよう。</small></div>${btn('settings','設定・おうちの方へ','','settings-link')}<small class="edition">小学4年生・おためし12文字</small></aside><div class="app-main"><header class="app-top"><span>きょうも、ひとつ発見しよう。</span><div><span class="top-count">✦ ${st.seen} <small>/ 12文字</small></span>${btn('sound',progress.settings.sound?'♪ 音 ON':'♪ 音 OFF','','sound-switch')}</div></header><main id="main">${body}${!storage?'<p class="storage-notice">このブラウザーでは記録を保存できません。そのまま遊べます。</p>':''}</main><footer class="app-footer">カンジ工房 <span>小さな部品が、漢字につながる。</span></footer></div></div>`;}
function home(){const st=studyStats(progress);return shell(`<section class="new-hero"><div><span class="eyebrow">ことば → かたち</span><h1>漢字のつくりを、<br>ことばで発見。</h1><p>「ひだりに、にんべん。みぎに、なか。」<br>部品の名前をえらんで、形にしてみよう。</p><span class="hero-chip">1回3文字。紙のじゅんびはいらないよ。</span></div><div class="hero-equation" aria-hidden="true"><span>にんべん</span><b>＋</b><span>なか</span><i>↓</i><strong>${glyph('仲')}</strong><small>名前が、形につながった！</small></div></section><div class="home-columns"><section class="panel start-panel"><span class="eyebrow">きょうの3文字</span><h2>ことばで組み立てよう</h2><div class="journey"><span><b>1</b>名前をえらぶ</span><i>→</i><span><b>2</b>形にする</span><i>→</i><span><b>3</b>たしかめる</span></div><div class="home-mode"><span>いつものモード</span>${modeSwitch()}</div>${btn('start','はじめる　→','','primary big-button')}<p class="micro">途中でもモードを切り替えられるよ。</p>${btn('review','もういちど練習する','','text-button')}</section><section class="panel status-panel"><span class="eyebrow">きみの発見</span><h2>できたことを、ひとつずつ。</h2><dl><div><dt>名前で組めた</dt><dd>${st.names}<small>文字</small></dd></div><div><dt>形を選んで組めた</dt><dd>${st.shape}<small>文字</small></dd></div><div><dt>ペンの形チェック</dt><dd>${st.pen}<small>文字</small></dd></div></dl>${btn('collection','ずかんを見る　→','','text-button')}</section></div><section class="panel component-entry"><div class="component-entry-mark">◇</div><div><span class="eyebrow">部品の名前、知ってる？</span><h2>部品から、ちょっと練習。</h2><p>「名前 → 形」と「形 → 名前」。わからない部品だけでも大丈夫。</p></div>${btn('parts','部品であそぶ　→','','secondary')}</section>`);}
function makeQuestion(item,type){return {item,stage:type==='part-form'?'output':'names',nameLayout:'lr',nameSlots:[null,null],nameActive:0,nameOptions:partCandidates(type==='kanji'?BY_CHAR[item].parts:[item],6),shapeOptions:partCandidates(type==='kanji'?BY_CHAR[item].parts:[item],12),shapeSlots:[null,null],shapeActive:0,ink:[],nameHints:[0,0],hints:[0,0],maxHints:[0,0],nameMistakes:0,mistakes:0,done:false,model:false,sawShape:false,resultMode:null};}
function start(items=studySession(progress).map(l=>l.char),type='kanji'){session={items,type,index:0,q:makeQuestion(items[0],type),results:[]};go('session');}
function currentParts(){return session.type==='kanji'?BY_CHAR[session.q.item].parts:[session.q.item];}
function currentTemplate(){return session.type==='kanji'?templates[session.q.item]:fitStrokes(partTemplates[session.q.item]||[]);}
function heading(){const s=session,q=s.q;if(s.type!=='kanji')return `<header class="task-heading"><span class="eyebrow">部品のれんしゅう</span><h1>${s.type==='part-name'?'この形の名前は？':`「${PARTS[q.item][1]}」は、どんな形？`}</h1>${s.type==='part-name'?`<div class="part-question">${partGlyph(q.item)}</div>`:'<p>名前を手がかりに、形を出してみよう。</p>'}</header>`;
  const l=BY_CHAR[q.item];return `<header class="task-heading"><span class="eyebrow">${q.stage==='names'?'まずは、ことばで組み立てよう':'ことばを、形にしてみよう'}</span><h1>「<strong>${html(l.wordReading)}</strong>」の<br class="phone-break">「<strong>${html(l.reading)}</strong>」の漢字</h1><p class="example-sentence">${html(l.sentence).replace(/［(.*?)］/g,'<mark>$1</mark>')}</p>${btn('read-question','♪ お題をきく','','text-button')}</header>`;
}
function sessionHeader(){return `<div class="study-toolbar">${btn(suspended?'return':'home',suspended?'← 元のお題へ':'← ホーム','','text-button')}<span class="question-number">${session.index+1} / ${session.items.length}</span>${modeSwitch()}</div>`;}
function namesBoard(){const q=session.q;if(session.type==='part-name')return `<div class="name-palette">${q.nameOptions.map(id=>btn('name-answer',html(PARTS[id][1]),`data-part="${id}"`,'name-option')).join('')}${btn('name-hint','名前のヒント','','hint-button')}</div>`;
  return `<div class="name-work"><div class="layout-toggle" role="group" aria-label="部品のならび方">${['lr','tb'].map(layout=>btn('name-layout',layout==='lr'?'ひだり・みぎ':'うえ・した',`data-layout="${layout}" aria-pressed="${q.nameLayout===layout}"`,q.nameLayout===layout?'selected':'')).join('')}</div><div class="name-board ${q.nameLayout}">${q.nameSlots.map((id,i)=>`<button class="name-slot ${q.nameActive===i?'active':''}" data-action="name-slot" data-slot="${i}"><small>${positions(q.nameLayout)[i]}に</small><strong>${id?html(PARTS[id][1]):'？'}</strong></button>`).join('')}</div><div class="palette-label"><strong>名前をえらんで、上のマスへ</strong>${btn('clear-names','入れなおす','','text-button')}</div><div class="name-palette">${q.nameOptions.map(id=>`<button class="name-option ${q.nameSlots.includes(id)?'used':''}" data-action="name" data-part="${id}" draggable="true">${html(PARTS[id][1])}</button>`).join('')}</div><div class="action-row">${btn('name-hint','名前のヒント','','hint-button')}${btn('check-names','この組み合わせで進む　→',q.nameSlots.some(v=>!v)?'disabled':'','primary')}</div></div>`;
}
function recipeBar(){if(session.type!=='kanji')return '';const l=BY_CHAR[session.q.item];return `<div class="recipe-bar"><span>きみが選んだ、漢字のつくり</span><p>${l.parts.map((id,i)=>`<span>${positions(l.layout)[i]}に <strong>${html(PARTS[id][1])}</strong></span>`).join('、')}</p>${btn('read-recipe','♪ ことばをきく','','text-button')}</div>`;}
function shapeBoard(){const q=session.q,ids=currentParts(),layout=session.type==='kanji'?BY_CHAR[q.item].layout:'lr';q.sawShape=true;return `<div class="shape-work"><div class="shape-board ${layout} ${ids.length===1?'single':''}" aria-label="部品を置くところ">${ids.map((_,i)=>`<button class="shape-slot ${q.shapeActive===i?'active':''}" data-action="shape-slot" data-slot="${i}">${q.shapeSlots[i]?partGlyph(q.shapeSlots[i]):`<span>＋</span><small>${ids.length===1?'ここへ':positions(layout)[i]}</small>`}</button>`).join('')}</div><div class="palette-label"><strong>12個の形から、えらぼう</strong>${btn('clear-shape','入れなおす','','text-button')}</div><div class="shape-palette">${q.shapeOptions.map((id,i)=>`<button class="shape-option ${q.shapeSlots.includes(id)?'used':''}" data-action="shape" data-part="${id}" draggable="true" aria-label="形の候補 ${i+1}">${partGlyph(id)}</button>`).join('')}</div><p class="micro">形をタップ。ドラッグでマスに置いてもいいよ。</p>${btn('check-shape','形をたしかめる　✦',ids.some((_,i)=>!q.shapeSlots[i])?'disabled':'','primary full-width')}</div>`;}
function penBoard(){return `<div class="pen-work"><div class="ink-board"><svg id="ink-pad" viewBox="0 0 109 109" role="img" aria-label="ペンで書く欄。指やマウスでも書けます"><path class="guidelines" d="M54.5 0V109M0 54.5H109"/><g id="ink-strokes">${session.q.ink.map(s=>`<path d="${strokePath(s)}"/>`).join('')}</g></svg><span class="ink-caption" ${session.q.ink.length?'hidden':''}>ここに書いてみよう</span></div><div class="ink-actions">${btn('undo','↶ 一画もどす','','text-button')}${btn('clear-ink','消して書きなおす','','text-button')}</div><p class="micro">指・マウスでも書けるよ。大きく、いつもの字で。</p>${btn('check-pen','書いた形をたしかめる　✦',session.q.ink.length?'':'disabled','primary full-width')}</div>`;}
function hintPanel(){const q=session.q,ids=currentParts(),isNames=q.stage==='names',levels=isNames?q.nameHints:q.hints;return `<section class="hint-panel"><div class="hint-panel-heading"><span>わからない部品だけ、ヒント</span>${q.stage==='output'?btn('model','見本をみる','','text-button'):''}</div><div class="hint-parts">${ids.map((id,i)=>`<div class="hint-part"><div class="hint-part-top"><strong>${isNames?(ids.length===1?'この部品':`${positions(BY_CHAR[q.item]?.layout||q.nameLayout)[i]}の部品`):html(PARTS[id][1])}</strong>${btn('part-hint',levels[i]===0?'① 名前をきく':levels[i]===1?'② 形をみる':levels[i]===2?'③ 書き順をみる':'もう一度きく',`data-slot="${i}"`,'hint-button')}</div>${levels[i]>=1?`<p class="hint-name">${html(PARTS[id][1])}</p>`:''}${levels[i]>=2?`<div class="hint-shape">${partGlyph(id,{animate:levels[i]>=3,numbered:levels[i]>=3})}</div>`:''}${levels[i]>=2&&session.type==='kanji'?btn('practice-part','この部品をれんしゅう',`data-part="${id}"`,'text-button'):''}</div>`).join('')}</div></section>`;}
function studyPage(){const q=session.q;return shell(`${sessionHeader()}<section class="study-panel panel ${q.done?'completed':''}">${heading()}${q.done?donePanel():q.stage==='names'?`${namesBoard()}${q.nameHints.some(Boolean)?hintPanel():''}`:`${recipeBar()}<div class="output-heading"><span>${progress.settings.mode==='shape'?'▦ 形から選ぶ':'✎ ペンで書く'}</span><small>${progress.settings.mode==='shape'?'部品名と、形をつなげよう':'見本なしで、形を出そう'}</small></div>${progress.settings.mode==='shape'?shapeBoard():penBoard()}${hintPanel()}`}<p class="feedback ${message?'visible':''}" role="status">${html(message)}</p></section>`);}
function donePanel(){const q=session.q,form=session.type!=='part-name';return `<div class="done-panel"><span class="done-star">✦</span><h2>${q.model?'見本でたしかめた！':!form?'名前がわかった！':q.resultMode==='pen'?'形のチェック、できた！':'部品が、つながった！'}</h2><div class="answer-glyph">${session.type==='kanji'?glyph(q.item,true):partGlyph(q.item)}</div><p>${session.type==='kanji'?html(recipe(BY_CHAR[q.item])):html(PARTS[q.item][1])}</p><span class="result-label">${q.model?'見本を見て確認':!form?'形 → 名前':q.resultMode==='pen'?`ペンの形チェック${q.sawShape?'・形を見た後':''}`:'12個の形から選べた'}</span>${q.model?btn('retry','見本を閉じて、もう一度','','secondary'):''}${btn('next',session.index===session.items.length-1?'今回のきろくへ　→':'つぎのお題へ　→','','primary')}</div>`;}
function resultPage(){return shell(`<section class="result-intro"><span class="eyebrow">きょうの小さな発見</span><h1>おつかれさま！</h1><p>ことばと形、少しつながったかな。</p></section><div class="session-results">${session.results.map(r=>`<section class="panel result-item"><div>${session.type==='kanji'?glyph(r.item):partGlyph(r.item)}</div><h2>${session.type==='kanji'?html(BY_CHAR[r.item].wordReading):html(PARTS[r.item][1])}</h2><p>${r.model?'見本でたしかめた':r.mode==='name'?'形から名前を選べた':r.mode==='pen'?'ペンの形チェック':'12個の形から選べた'}</p><small>${r.assisted?'ヒントや、やりなおしも使ったよ':'ヒントなしで確かめたよ'}</small></section>`).join('')}</div><div class="result-actions">${suspended?btn('return','元のお題にもどる　→','','primary'):btn('start','べつの3文字であそぶ　→','','primary')}${btn('parts','部品のれんしゅう','','secondary')}${btn('home','ホームへ','','text-button')}</div>`);}
function partPage(){return shell(`<section class="page-heading"><span class="eyebrow">部品から、はじめてもいい。</span><h1>名前と形の、部品ずかん</h1><p>名前を見て、形を見て。ひとつだけでも練習しよう。</p>${suspended?btn('return','← 元のお題にもどる','','secondary'):''}</section><div class="part-library">${Object.keys(PARTS).map(id=>`<section class="panel part-card"><div>${partGlyph(id)}</div><h2>${html(PARTS[id][1])}</h2>${btn('speak-part','♪ 名前をきく',`data-part="${id}"`,'text-button')}<div>${btn('start-part-name','形 → 名前',`data-part="${id}"`,'soft')}${btn('start-part-form','名前 → 形',`data-part="${id}"`,'soft')}</div><p class="micro">名前 ${progress.parts[id]?.name.successes||0} 回 · 形 ${progress.parts[id]?.shape.successes||0} 回 · ペン ${progress.parts[id]?.pen.successes||0} 回</p></section>`).join('')}</div>`);}
function collectionPage(){const l=detail&&BY_CHAR[detail];return shell(`<section class="page-heading"><span class="eyebrow">できたことを、分けて残す。</span><h1>漢字ずかん</h1><p>「形を選べた」と「ペンの形チェック」は別のきろく。</p></section>${l?`<section class="panel collection-detail">${glyph(l.char)}<div><h2>${l.word} <small>${l.wordReading}</small></h2><p>${l.meaning}</p><p>${html(recipe(l))}</p>${btn('start-char','この漢字であそぶ　→',`data-char="${l.char}"`,'primary')}</div></section>`:''}<div class="kanji-library">${LESSONS.map(l=>{const r=progress.records[l.char];return `<button class="panel kanji-card" data-action="detail" data-char="${l.char}">${glyph(l.char)}<h2>${l.word}</h2><p>${l.wordReading}</p><div class="record-lines"><span>名前 <b>${r?.names.successes||0}回</b></span><span>形選択 <b>${r?.shape.successes||0}回</b></span><span>ペン <b>${r?.pen.successes||0}回</b></span></div>${progress.legacy.records[l.char]?.collected?'<small class="legacy-badge">旧版で遊んだ記録あり</small>':''}</button>`;}).join('')}</div>`);}
function settingsPage(){return shell(`<section class="page-heading"><h1>設定・おうちの方へ</h1></section><section class="panel parent-panel"><h2>いつものモード</h2>${modeSwitch()}<p>最後に使ったモードを、このブラウザーに保存します。毎問選び直す必要はありません。</p><h2>学習の流れ</h2><p>ひらがなの部品名で構成を答えてから、形を選ぶかペンで書きます。部品の名前・形・組み合わせを言葉で扱うミチムラ式と、つまずいた所を短く覚え直して確認するさかもと式を参考にした独自の試作です。公式教材ではありません。</p><h2>ペンの「形チェック」について</h2><p>同梱の筆画データと筆跡の形を端末内で比較します。文字認識や厳密な採点ではなく、筆順・細かなとめ・はね・はらいは評価しません。正しい字でも通らない場合や、似た形が通る場合があります。実際の書字の習得を保証するものではありません。うまく判定されない時は、見本を確認して先へ進めます。</p><h2>記録の区別</h2><p>名前選択、12候補の形選択、構成文を見ながらのペンの形チェック、見本確認を区別します。形の候補やヒントを見た後のペン入力も支援ありとして残します。旧版の記録は保持し、新しい学習の成功には移し替えません。</p><h2>記録の持ち運び</h2><p>結果と設定はこのブラウザー内に保存します。筆跡・音声の外部送信はしません。別の端末やURLへ移す場合は、書き出したJSONを読み込んでください。読み込みは現在の記録を置き換えます。</p><div class="transfer-buttons">${btn('export','きろくを書き出す','','secondary')}<label class="secondary">きろくを読みこむ<input type="file" id="import-progress" accept=".json,application/json"></label></div><p role="status">${html(message)}</p><h2>参考・字形の出典</h2><div class="credits"><a href="https://kanji.cloud/studymethod/method-features/" target="_blank" rel="noopener noreferrer">ミチムラ式公式の説明</a><a href="https://manatera.com/kanji/" target="_blank" rel="noopener noreferrer">さかもと式公式の説明</a><a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener noreferrer">KanjiVG © Ulrich Apel</a><a href="./ATTRIBUTION.txt">筆画データ CC BY-SA 3.0・出典</a></div><p>部品の名前・分け方は本試作の学習補助です。字源の説明ではありません。収録は小学4年生の12字です。</p></section>`);}
function render(){const focus=document.activeElement?.dataset?{...document.activeElement.dataset}:null;app.innerHTML=screen==='home'?home():screen==='session'?studyPage():screen==='results'?resultPage():screen==='parts'?partPage():screen==='collection'?collectionPage():settingsPage();if(focus?.action)[...app.querySelectorAll('[data-action]')].find(el=>!el.disabled&&Object.entries(focus).every(([k,v])=>el.dataset[k]===v))?.focus({preventScroll:true});}

function put(id,index){const q=session?.q;if(!q||q.done)return;const names=q.stage==='names';if(names&&session.type!=='kanji')return;const slots=names?q.nameSlots:q.shapeSlots,active=names?q.nameActive:q.shapeActive,n=currentParts().length;if(!(names?q.nameOptions:q.shapeOptions).includes(id))return;const target=index??active,previous=slots.indexOf(id);if(previous>=0)slots[previous]=null;slots[target]=id;const next=slots.slice(0,n).findIndex(v=>!v);if(names)q.nameActive=next<0?0:next;else q.shapeActive=next<0?0:next;message='';render();}
function complete({model=false,mode=progress.settings.mode}={}){const s=session,q=s.q;if(q.done)return;q.done=true;q.model=model;q.resultMode=mode;const options={hints:q.stage==='names'?q.nameHints:q.maxHints,mistakes:q.stage==='names'?q.nameMistakes:q.mistakes,model,sawShape:mode==='pen'&&q.sawShape};if(s.type==='kanji')progress=recordStudy(progress,q.item,mode,options);else progress=recordPart(progress,q.item,s.type==='part-name'?'name':mode,options);save();sound();message='';render();say(model?'見本でたしかめたよ。':'できた！');}
function namesCorrect(){const q=session.q;if(q.stage!=='names'||q.done)return;progress=recordStudy(progress,q.item,'names',{hints:q.nameHints,mistakes:q.nameMistakes});save();q.stage='output';message='名前の組み合わせ、できた！ 次はその下で形にしよう。';sound();render();}
function useHint(index){const q=session.q,ids=currentParts(),levels=q.stage==='names'?q.nameHints:q.hints;if(!ids[index])return;levels[index]=Math.min(3,levels[index]+1);if(q.stage==='output')q.maxHints[index]=Math.max(q.maxHints[index],levels[index]);if(levels[index]===1||levels[index]===3)speak(PARTS[ids[index]][1]);if(levels[index]>=2)q.sawShape=true;message='';render();}
app.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
  if(suppressClick&&['name','shape','name-slot','shape-slot'].includes(a)){event.preventDefault();return;}
  if(a==='home'){suspended=null;go('home');return;}
  if(a==='return'&&suspended){session=suspended;suspended=null;go('session');return;}
  if(['parts','settings','collection'].includes(a)){detail=null;go(a);return;}
  if(a==='start'){suspended=null;start();return;}
  if(a==='review'){suspended=null;start(studySession(progress,{review:true}).map(l=>l.char));return;}
  if(a==='start-char'){suspended=null;start([el.dataset.char]);return;}
  if(a==='detail'){detail=el.dataset.char;render();return;}
  if(a==='sound'){progress.settings.sound=!progress.settings.sound;save();render();return;}
  if(a==='mode'){progress.settings.mode=el.dataset.mode==='pen'?'pen':'shape';save();message='';render();return;}
  if(a==='speak-part'){speak(PARTS[el.dataset.part][1]);return;}
  if(a==='start-part-name'||a==='start-part-form'){start([el.dataset.part],a==='start-part-name'?'part-name':'part-form');return;}
  if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`kanji-kobo-${localDate()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(screen!=='session')return;const q=session.q;
  if(a==='read-question'){const l=BY_CHAR[q.item];speak(`${l.wordReading} の ${l.reading}。${l.sentence.replace(/[［］]/g,'')}`);return;}
  if(a==='read-recipe'){speak(recipe(BY_CHAR[q.item]));return;}
  if(q.done&&!['next','retry'].includes(a))return;
  if(a==='name'||a==='shape'){put(el.dataset.part);return;}
  if(a==='name-slot'||a==='shape-slot'){const i=Number(el.dataset.slot);if(a==='name-slot'){q.nameSlots[i]=null;q.nameActive=i;}else{q.shapeSlots[i]=null;q.shapeActive=i;}message='';render();return;}
  if(a==='name-layout'){q.nameLayout=el.dataset.layout;message='';render();return;}
  if(a==='clear-names'){q.nameSlots=[null,null];q.nameActive=0;message='';render();return;}
  if(a==='clear-shape'){q.shapeSlots=[null,null];q.shapeActive=0;message='';render();return;}
  if(a==='name-hint'){q.nameHints[0]=Math.max(1,q.nameHints[0]);speak(PARTS[currentParts()[0]][1]);message='部品ごとのヒントを下に開いたよ。';render();return;}
  if(a==='part-hint'){useHint(Number(el.dataset.slot));return;}
  if(a==='practice-part'){if(session.type!=='kanji')return;q.sawShape=true;const i=currentParts().indexOf(el.dataset.part);(q.stage==='names'?q.nameHints:q.hints)[i]=3;if(q.stage==='output')q.maxHints[i]=3;suspended=session;start([el.dataset.part],'part-form');return;}
  if(a==='check-names'){if(isCorrect(BY_CHAR[q.item],q.nameLayout,q.nameSlots))namesCorrect();else{q.nameMistakes++;message='おしい！ 名前と、ならび方をもう一度。わからなければヒントを使おう。';render();say(message);}return;}
  if(a==='name-answer'){if(el.dataset.part===q.item)complete({mode:'name'});else{q.nameMistakes++;message='もう一度、名前をえらんでみよう。';render();}return;}
  if(a==='check-shape'){if(currentParts().every((id,i)=>q.shapeSlots[i]===id))complete();else{q.mistakes++;message='おしい！ 部品の形や、置く場所をもう一度たしかめよう。';render();say(message);}return;}
  if(a==='clear-ink'||a==='undo'){drawing=null;if(a==='undo')q.ink.pop();else q.ink=[];message='';render();return;}
  if(a==='check-pen'){if(compareInk(q.ink,currentTemplate()).ok)complete();else{q.mistakes++;message='まだ形を確かめきれなかったよ。部品のヒントを見たり、書きなおしたりしてみよう。書けているのに進めない時は、見本で確認できるよ。';render();say(message);}return;}
  if(a==='model'){q.sawShape=true;complete({model:true});return;}
  if(a==='retry'){q.done=false;q.stage=session.type==='part-name'?'names':'output';q.model=false;q.ink=[];q.shapeSlots=[null,null];q.shapeActive=0;q.hints=[0,0];q.mistakes++;message='見本を閉じたよ。もう一度、形にしてみよう。';render();return;}
  if(a==='next'){session.results.push({item:q.item,mode:q.resultMode,model:q.model,assisted:q.model||q.mistakes>0||q.nameMistakes>0||q.hints.some(Boolean)||q.nameHints.some(Boolean)||(q.resultMode==='pen'&&q.sawShape)});if(session.index<session.items.length-1){session.index++;session.q=makeQuestion(session.items[session.index],session.type);message='';render();window.scrollTo({top:0,behavior:'instant'});}else{progress.sessions++;save();go('results');}return;}
});

// 筆跡は109×109の座標に保持。ヒントやモード切替の再描画でも失わない。
function inkPoint(event,pad){const r=pad.getBoundingClientRect();return [Math.max(0,Math.min(109,(event.clientX-r.left)/r.width*109)),Math.max(0,Math.min(109,(event.clientY-r.top)/r.height*109))];}
function updateInk(){const g=document.querySelector('#ink-strokes');if(!g)return;g.replaceChildren(...session.q.ink.map(s=>{const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',strokePath(s));return p;}));const caption=document.querySelector('.ink-caption');if(caption)caption.hidden=session.q.ink.length>0;const b=document.querySelector('[data-action="check-pen"]');if(b)b.disabled=session.q.ink.length===0;}
app.addEventListener('pointerdown',event=>{const pad=event.target.closest('#ink-pad');if(pad){if(session.q.done||drawing||event.button>0||event.pointerType==='touch'&&event.width>35)return;event.preventDefault();const stroke=[inkPoint(event,pad)];session.q.ink.push(stroke);drawing={id:event.pointerId,pad,stroke};pad.setPointerCapture?.(event.pointerId);updateInk();return;}const el=event.target.closest('[data-action="name"],[data-action="shape"]');if(el&&['touch','pen'].includes(event.pointerType)&&!session.q.done){drag={id:el.dataset.part,element:el,pointerId:event.pointerId,x:event.clientX,y:event.clientY,moved:false,ghost:null};el.setPointerCapture?.(event.pointerId);}});
app.addEventListener('pointermove',event=>{if(drawing&&event.pointerId===drawing.id){event.preventDefault();const events=event.getCoalescedEvents?.();for(const e of events?.length?events:[event]){const p=inkPoint(e,drawing.pad),last=drawing.stroke.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])>.35)drawing.stroke.push(p);}updateInk();return;}if(!drag||event.pointerId!==drag.pointerId)return;if(!drag.moved&&Math.hypot(event.clientX-drag.x,event.clientY-drag.y)<8)return;drag.moved=true;event.preventDefault();if(!drag.ghost){drag.ghost=document.createElement('div');drag.ghost.className='drag-ghost';drag.ghost.textContent=session.q.stage==='names'?PARTS[drag.id][1]:PARTS[drag.id][0];document.body.append(drag.ghost);}drag.ghost.style.left=`${event.clientX}px`;drag.ghost.style.top=`${event.clientY}px`;dropPreview(event.clientX,event.clientY);});
function endPointer(event,cancel=false){if(drawing&&event.pointerId===drawing.id){const d=drawing;drawing=null;if(cancel){session.q.ink=session.q.ink.filter(s=>s!==d.stroke);}else{const p=inkPoint(event,d.pad);if(Math.hypot(p[0]-d.stroke.at(-1)[0],p[1]-d.stroke.at(-1)[1])>.2)d.stroke.push(p);}updateInk();d.pad.releasePointerCapture?.(event.pointerId);return;}if(!drag||event.pointerId!==drag.pointerId)return;const d=drag;drag=null;d.ghost?.remove();clearDrop();if(d.moved){suppressClick=true;setTimeout(()=>suppressClick=false,50);if(!cancel)dropPart(d.id,event.clientX,event.clientY);}}
app.addEventListener('pointerup',e=>endPointer(e));app.addEventListener('pointercancel',e=>endPointer(e,true));app.addEventListener('lostpointercapture',e=>endPointer(e,true));
function clearDrop(){app.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));}
function destination(x,y){const names=session?.q.stage==='names',board=app.querySelector(names?'.name-board':'.shape-board');if(!board)return null;const layout=names?session.q.nameLayout:session.type==='kanji'?BY_CHAR[session.q.item].layout:'lr',r=board.getBoundingClientRect();if(currentParts().length===1)return x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom?{slot:0,layout}:null;const p=placementAt(r,x,y,layout);if(!p)return null;if(!names)p.layout=layout;p.slot=(p.layout==='lr'?(x-r.left)/r.width:(y-r.top)/r.height)<.5?0:1;return p;}
function dropPreview(x,y){clearDrop();const p=destination(x,y);if(p)app.querySelectorAll(session.q.stage==='names'?'.name-slot':'.shape-slot')[p.slot]?.classList.add('drop-target');return p;}
function dropPart(id,x,y){const p=destination(x,y);if(p){if(session.q.stage==='names')session.q.nameLayout=p.layout;put(id,p.slot);}clearDrop();}
app.addEventListener('dragstart',event=>{const el=event.target.closest('[data-action="name"],[data-action="shape"]');if(!el||session.q.done)return;nativePart=el.dataset.part;event.dataTransfer.setData('text/plain',nativePart);event.dataTransfer.effectAllowed='move';});
app.addEventListener('dragover',event=>{if(nativePart&&dropPreview(event.clientX,event.clientY))event.preventDefault();});
app.addEventListener('drop',event=>{if(!nativePart)return;event.preventDefault();const id=nativePart;nativePart=null;dropPart(id,event.clientX,event.clientY);});
app.addEventListener('dragend',()=>{nativePart=null;clearDrop();});
app.addEventListener('change',async event=>{if(event.target.id!=='import-progress')return;const file=event.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw new Error('size');const raw=JSON.parse(await file.text());if(![1,2].includes(raw?.version)||!raw.records||typeof raw.records!=='object'||Array.isArray(raw.records))throw new Error('format');progress=normalizeStudy(raw);save();message='きろくを読みこみました。';}catch{message='記録を読みこめませんでした。カンジ工房のJSONファイルを選んでください。';}render();});
try{const response=await fetch('./glyphs.json');if(!response.ok)throw new Error('glyphs');glyphs=await response.json();for(const l of LESSONS){templates[l.char]=glyphs[l.char].flat().map(samplePath);l.parts.forEach((id,i)=>{if(!partPaths[id]){partPaths[id]=glyphs[l.char][i];partTemplates[id]=partPaths[id].map(samplePath);}});}}catch{say('筆画データを読み込めませんでした。再読み込みすると、形のヒントとペンの確認が使えます。');}
render();
